        "content": "/* NeoMarket Admin Styles - Matrix/Terminal Inspired */\n\n.neomarket-admin-wrap {\n    background: #0d1117;\n    color: #39ff14; /* Matrix Green */\n    font-family: 'Courier New', Courier, monospace;\n    padding: 20px;\n    border-radius: 8px;\n}\n\n.neomarket-admin-wrap h1, .neomarket-admin-wrap h2 {\n    color: #39ff14;\n    text-shadow: 0 0 5px rgba(57, 255, 20, 0.5);\n}\n\n.neomarket-admin-wrap .card {\n    background: #161b22 !important;\n    border: 1px solid #30363d !important;\n    color: #c9d1d9 !important;\n}\n\n.neomarket-admin-wrap .button {\n    background: #238636 !important;\n    border-color: #2ea043 !important;\n    color: #fff !important;\n    text-transform: uppercase;\n    font-weight: bold;\n}\n\n/* Metabox Styles */\n.post-type-neo_product #poststuff .postbox {\n    background: #161b22;\n    border-color: #30363d;\n    color: #c9d1d9;\n}\n\n.post-type-neo_product .postbox-header {\n    border-bottom-color: #30363d;\n}\n\n.post-type-neo_product .postbox-header h2 {\n    color: #39ff14;\n}\n\n.neomarket-metabox-wrapper input[type=\"text\"], \n.neomarket-metabox-wrapper input[type=\"number\"],\n.neomarket-metabox-wrapper select,\n.neomarket-metabox-wrapper textarea {\n    background: #0d1117;\n    border: 1px solid #30363d;\n    color: #39ff14;\n    padding: 8px;\n}\n\n.neomarket-spec-item {\n    background: #0d1117;\n    padding: 10px;\n    border: 1px dashed #39ff14;\n    margin-bottom: 10px;\n}\n\n#neomarket-footer-credit {\n    border-top: 1px solid #30363d !important;\n    color: #8b949e !important;\n}\n\n#neomarket-footer-credit strong {\n    color: #39ff14;\n}\n"
