        "content": ".neo-admin-shell {\n    --neo-bg: #05070a;\n    --neo-panel: rgba(8, 12, 18, 0.92);\n    --neo-border: #1f6f42;\n    --neo-text: #d7ffe6;\n    --neo-muted: #8ab89b;\n    --neo-accent: #33ff77;\n    --neo-shadow: 0 0 0 1px rgba(51, 255, 119, 0.15), 0 18px 40px rgba(0, 0, 0, 0.35);\n    color: var(--neo-text);\n}\n\n.neo-admin-shell *,\n.neo-admin-shell *::before,\n.neo-admin-shell *::after {\n    box-sizing: border-box;\n}\n\n.neo-admin-shell .neo-admin-card,\n.neo-admin-shell .neo-panel {\n    background:\n        linear-gradient(180deg, rgba(20, 27, 38, 0.96), rgba(5, 7, 10, 0.98)),\n        repeating-linear-gradient(0deg, rgba(51, 255, 119, 0.03) 0, rgba(51, 255, 119, 0.03) 1px, transparent 1px, transparent 24px);\n    border: 1px solid var(--neo-border);\n    box-shadow: var(--neo-shadow);\n    border-radius: 12px;\n}\n\n.neo-admin-shell .neo-admin-card {\n    padding: 24px;\n    margin-top: 20px;\n}\n\n.neo-admin-heading {\n    display: flex;\n    justify-content: space-between;\n    align-items: flex-start;\n    gap: 16px;\n    margin-bottom: 24px;\n}\n\n.neo-admin-heading h1,\n.neo-admin-shell h2 {\n    color: var(--neo-accent);\n    font-family: \"Courier New\", monospace;\n    letter-spacing: 0.04em;\n}\n\n.neo-admin-heading p,\n.neo-admin-shell p,\n.neo-admin-shell li,\n.neo-admin-shell label,\n.neo-admin-shell td,\n.neo-admin-shell th {\n    color: var(--neo-text);\n}\n\n.neo-admin-badge,\n.neo-notice {\n    font-family: \"Courier New\", monospace;\n    background: rgba(51, 255, 119, 0.08);\n    border: 1px solid rgba(51, 255, 119, 0.35);\n    color: var(--neo-accent);\n    padding: 10px 14px;\n    border-radius: 999px;\n}\n\n.neo-notice {\n    margin-bottom: 20px;\n    border-radius: 10px;\n}\n\n.neo-panel-grid {\n    display: grid;\n    grid-template-columns: 2fr 1fr;\n    gap: 20px;\n    margin-bottom: 24px;\n}\n\n.neo-panel {\n    padding: 20px;\n}\n\n.neo-panel-full {\n    margin-top: 20px;\n}\n\n.neo-grid-row {\n    display: grid;\n    grid-template-columns: 180px 1fr;\n    gap: 16px;\n    align-items: center;\n    margin-bottom: 14px;\n}\n\n.neo-label {\n    font-weight: 600;\n}\n\n.neo-field-wrap input[type=\"text\"],\n.neo-field-wrap input[type=\"url\"],\n.neo-field-wrap input[type=\"number\"],\n.neo-field-wrap select,\n.neo-field-wrap textarea,\n.neo-table input[type=\"text\"],\n.neo-table input[type=\"url\"],\n.neo-table input[type=\"number\"],\n.neo-table select {\n    width: 100%;\n    min-height: 42px;\n    background: #05070a;\n    border: 1px solid #215939;\n    color: var(--neo-text);\n    border-radius: 8px;\n    padding: 8px 12px;\n}\n\n.neo-table .small-text {\n    width: 84px;\n}\n\n.neo-color-field {\n    max-width: 140px;\n}\n\n.neo-media-picker {\n    display: flex;\n    gap: 8px;\n    align-items: center;\n}\n\n.neo-media-picker .button,\n.neo-actions .button,\n.neo-switch span {\n    border-radius: 8px;\n}\n\n.neo-admin-shell .button,\n.neo-admin-shell .button.button-primary {\n    background: #0c1610;\n    color: var(--neo-accent);\n    border: 1px solid #2ea85f;\n    text-shadow: none;\n    box-shadow: none;\n}\n\n.neo-admin-shell .button.button-primary {\n    background: linear-gradient(180deg, #0f2b19, #09120d);\n}\n\n.neo-callout {\n    border: 1px dashed rgba(51, 255, 119, 0.35);\n    padding: 16px;\n    background: rgba(3, 7, 11, 0.7);\n    border-radius: 10px;\n}\n\n.neo-switch {\n    display: inline-flex;\n    align-items: center;\n    gap: 10px;\n}\n\n.neo-table-wrap {\n    overflow-x: auto;\n}\n\n.neo-table {\n    background: transparent;\n    border-color: rgba(51, 255, 119, 0.18);\n}\n\n.neo-table th,\n.neo-table td {\n    background: rgba(5, 7, 10, 0.8);\n    border-bottom-color: rgba(51, 255, 119, 0.1);\n    vertical-align: top;\n}\n\n.neo-muted,\n.neo-admin-shell .description {\n    color: var(--neo-muted);\n}\n\n.neo-actions {\n    margin-top: 20px;\n}\n\n@media (max-width: 960px) {\n    .neo-panel-grid {\n        grid-template-columns: 1fr;\n    }\n\n    .neo-grid-row {\n        grid-template-columns: 1fr;\n    }\n\n    .neo-media-picker {\n        flex-direction: column;\n        align-items: stretch;\n    }\n}\n"
