        "content": "#neoloadland-overlay {\n    position: fixed;\n    inset: 0;\n    z-index: 999999;\n    background-size: cover;\n    background-position: center;\n    background-repeat: no-repeat;\n    transition: opacity 0.65s ease, visibility 0.65s ease;\n}\n\n#neoloadland-overlay.is-hiding {\n    opacity: 0;\n    visibility: hidden;\n    pointer-events: none;\n}\n\n.neoloadland-content {\n    display: flex;\n    width: 100%;\n    height: 100%;\n    padding: 36px;\n}\n\n.neoloadland-inner {\n    display: inline-flex;\n    flex-direction: column;\n    align-items: center;\n    justify-content: center;\n    gap: 14px;\n    text-align: center;\n}\n\n.neoloadland-media {\n    display: block;\n    max-width: min(80vw, 420px);\n    height: auto;\n    object-fit: contain;\n}\n\n.neoloadland-message {\n    line-height: 1.45;\n    letter-spacing: 0.03em;\n}\n\n.neoloadland-fallback {\n    display: grid;\n    place-items: center;\n    border: 1px solid rgba(255, 255, 255, 0.18);\n    background: rgba(255, 255, 255, 0.04);\n    color: #9dff7a;\n    font-family: \"Courier New\", monospace;\n    font-size: 32px;\n    border-radius: 18px;\n}\n"
