        "content": "html.neolock-active,\nbody.neolock-active {\n    -webkit-tap-highlight-color: transparent !important;\n}\n\n.neolock-img-wrap {\n    position: relative;\n    display: inline-block;\n    max-width: 100%;\n    vertical-align: top;\n    z-index: 0;\n}\n\n.neolock-img-wrap img {\n    display: block;\n    max-width: 100%;\n    height: auto;\n    -webkit-user-drag: none;\n    user-drag: none;\n    -webkit-touch-callout: none;\n    pointer-events: none;\n}\n\n.neolock-img-shield {\n    position: absolute;\n    inset: 0;\n    z-index: 2;\n    background-color: rgba(0, 0, 0, 0.001);\n    pointer-events: auto;\n    -webkit-user-drag: none;\n    user-drag: none;\n    -webkit-touch-callout: none;\n}\n\n.neolock-watermark {\n    position: fixed;\n    inset: 0;\n    pointer-events: none;\n    z-index: 999998;\n    overflow: hidden;\n    background-repeat: repeat;\n    background-position: 0 0;\n}\n\n.neolock-shield {\n    position: fixed;\n    inset: 0;\n    z-index: 2147483647;\n    background: #000000;\n    pointer-events: none;\n    opacity: 0;\n    visibility: hidden;\n    transition: opacity 120ms linear, visibility 120ms linear;\n    display: grid;\n    place-items: center;\n    padding: 40px;\n    text-align: center;\n}\n\n.neolock-shield.is-active {\n    opacity: 1;\n    visibility: visible;\n    pointer-events: auto;\n}\n\n.neolock-shield::before {\n    content: attr(data-neolock-msg);\n    display: grid;\n    place-items: center;\n    max-width: 780px;\n    line-height: 1.8;\n    letter-spacing: 0.14em;\n    color: #33ff77;\n    font-family: \"Courier New\", monospace;\n    font-weight: 700;\n    font-size: clamp(16px, 2.2vw, 26px);\n    border: 2px solid rgba(51, 255, 119, 0.45);\n    padding: 40px 50px;\n    border-radius: 12px;\n    background:\n        linear-gradient(180deg, rgba(10, 18, 12, 0.96), rgba(0, 0, 0, 1)),\n        repeating-linear-gradient(0deg, rgba(51, 255, 119, 0.04) 0, rgba(51, 255, 119, 0.04) 1px, transparent 1px, transparent 24px);\n    white-space: pre-wrap;\n}\n\n@media print {\n    html.neolock-active #neolock-print-warning {\n        display: grid !important;\n        visibility: visible !important;\n    }\n}\n"
